schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/growth-viral-loops.json",
  "title": "Growth Viral Loops spec",
  "type": "object",
  "required": ["loop_name", "primary_loop", "k_factor", "cycle_time", "projection", "k_target", "invitee_path", "friction_experiments", "events", "retention", "incentive", "consent_and_disclosure"],
  "additionalProperties": false,
  "definitions": {
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "measured": {
      "type": "object",
      "required": ["value", "window_days", "sample_size"],
      "additionalProperties": false,
      "properties": {
        "value": {"type": "number", "minimum": 0},
        "window_days": {"type": "integer", "minimum": 1},
        "sample_size": {"type": "integer", "minimum": 1}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "loop_name": {"type": "string", "minLength": 3},
    "primary_loop": {
      "type": "object",
      "required": ["share_event", "kind", "value_to_inviter", "secondary_loop"],
      "additionalProperties": false,
      "properties": {
        "share_event": {"allOf": [{"$ref": "#/definitions/event_name"}, {"not": {"enum": ["invite_modal_shown", "refer_page_viewed", "referral_page_viewed", "invite_friends_modal"]}}]},
        "kind": {"const": "inherent"},
        "value_to_inviter": {"type": "string", "minLength": 20},
        "secondary_loop": {
          "anyOf": [
            {"type": "null"},
            {
              "type": "object",
              "required": ["surface", "k"],
              "additionalProperties": false,
              "properties": {
                "surface": {"type": "string", "enum": ["invite_modal", "referral_page"]},
                "k": {"type": "number", "minimum": 0}
              }
            }
          ]
        }
      }
    },
    "k_factor": {
      "type": "object",
      "required": ["invites_per_active_user", "accept_rate_per_invite", "k", "cycles_measured"],
      "additionalProperties": false,
      "properties": {
        "invites_per_active_user": {"$ref": "#/definitions/measured"},
        "accept_rate_per_invite": {"allOf": [{"$ref": "#/definitions/measured"}, {"properties": {"value": {"maximum": 1}}}]},
        "k": {"type": "number", "minimum": 0},
        "cycles_measured": {"type": "integer", "minimum": 2}
      }
    },
    "cycle_time": {
      "type": "object",
      "required": ["days", "method", "sample_size"],
      "additionalProperties": false,
      "properties": {
        "days": {"type": "number", "exclusiveMinimum": 0},
        "method": {"const": "send_to_first_send_timestamps"},
        "sample_size": {"type": "integer", "minimum": 1}
      }
    },
    "projection": {
      "type": "object",
      "required": ["starting_users", "days", "projected_users", "ignores_churn"],
      "additionalProperties": false,
      "properties": {
        "starting_users": {"type": "integer", "minimum": 1},
        "days": {"type": "integer", "minimum": 30},
        "projected_users": {"type": "integer", "minimum": 1},
        "ignores_churn": {"const": true}
      }
    },
    "k_target": {
      "type": "object",
      "required": ["current_k", "target_k", "kind", "benchmark"],
      "additionalProperties": false,
      "properties": {
        "current_k": {"type": "number", "minimum": 0},
        "target_k": {"type": "number", "exclusiveMinimum": 0},
        "kind": {"type": "string", "enum": ["self_sustaining", "increment"]},
        "benchmark": {
          "type": "object",
          "required": ["range_low", "range_high", "source"],
          "additionalProperties": false,
          "properties": {
            "range_low": {"type": "number", "minimum": 0},
            "range_high": {"type": "number", "minimum": 0},
            "source": {"type": "string", "minLength": 10}
          }
        }
      },
      "if": {"properties": {"current_k": {"exclusiveMaximum": 0.4}}},
      "then": {"properties": {"target_k": {"maximum": 1}, "kind": {"const": "increment"}}}
    },
    "invitee_path": {
      "type": "array",
      "minItems": 1,
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["name", "conversion"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "conversion": {"$ref": "#/definitions/rate"}
        }
      }
    },
    "friction_experiments": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "target_step", "current_conversion", "expected_conversion"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 10},
          "target_step": {"type": "string", "minLength": 3},
          "current_conversion": {"$ref": "#/definitions/rate"},
          "expected_conversion": {"$ref": "#/definitions/rate"}
        }
      }
    },
    "events": {
      "type": "array",
      "minItems": 5,
      "items": {
        "type": "object",
        "required": ["name", "keys"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["invite_shown", "invite_sent", "invite_opened", "invite_accepted", "invitee_activated"]},
          "keys": {"type": "array", "items": {"type": "string"}, "allOf": [{"contains": {"const": "invite_id"}}, {"contains": {"const": "inviter_user_id"}}]}
        }
      }
    },
    "retention": {
      "type": "object",
      "required": ["invitee_d30", "organic_d30"],
      "additionalProperties": false,
      "properties": {
        "invitee_d30": {"$ref": "#/definitions/rate"},
        "organic_d30": {"$ref": "#/definitions/rate"}
      }
    },
    "incentive": {
      "anyOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["referrer_reward", "invitee_reward", "trigger_milestone", "window_days", "max_rewards_per_referrer_per_12_months", "self_referral_block", "excludes_existing_and_past_users"],
          "additionalProperties": false,
          "properties": {
            "referrer_reward": {"type": "string", "minLength": 3},
            "invitee_reward": {"type": "string", "minLength": 3},
            "trigger_milestone": {"allOf": [{"$ref": "#/definitions/event_name"}, {"not": {"enum": ["signup", "signup_completed", "account_created", "invite_accepted"]}}]},
            "window_days": {"type": "integer", "minimum": 1},
            "max_rewards_per_referrer_per_12_months": {"type": "integer", "minimum": 1},
            "self_referral_block": {"type": "array", "items": {"type": "string", "enum": ["device_fingerprint", "ip", "payment_instrument", "normalised_email"]}, "allOf": [{"contains": {"const": "device_fingerprint"}}, {"contains": {"const": "ip"}}, {"contains": {"const": "payment_instrument"}}]},
            "excludes_existing_and_past_users": {"const": true}
          }
        }
      ]
    },
    "consent_and_disclosure": {
      "type": "object",
      "required": ["recipient_source", "casl_express_consent", "gdpr_lawful_basis", "compensation_disclosure"],
      "additionalProperties": false,
      "properties": {
        "recipient_source": {"type": "string", "enum": ["entered_by_inviter", "consented_contact_import"]},
        "casl_express_consent": {"const": true},
        "gdpr_lawful_basis": {"type": "string", "enum": ["consent", "contract", "legitimate_interest"]},
        "compensation_disclosure": {"type": "string", "enum": ["not_applicable", "message", "landing_page", "both"]}
      }
    }
  }
}

output-contract.example:
{
  "loop_name": "board collaboration loop",
  "primary_loop": {
    "share_event": "board_shared",
    "kind": "inherent",
    "value_to_inviter": "the inviter needs the collaborator on the board to finish the work; sharing is the product action, not a favour",
    "secondary_loop": null
  },
  "k_factor": {
    "invites_per_active_user": {"value": 1.8, "window_days": 30, "sample_size": 12400},
    "accept_rate_per_invite": {"value": 0.36, "window_days": 30, "sample_size": 22300},
    "k": 0.648,
    "cycles_measured": 3
  },
  "cycle_time": {"days": 6, "method": "send_to_first_send_timestamps", "sample_size": 4100},
  "projection": {"starting_users": 1000, "days": 90, "projected_users": 2838, "ignores_churn": true},
  "k_target": {
    "current_k": 0.648,
    "target_k": 0.8,
    "kind": "increment",
    "benchmark": {"range_low": 0.05, "range_high": 0.2, "source": "widely cited practitioner benchmarks for B2B SaaS, as listed in templates/loop-projection.py"}
  },
  "invitee_path": [
    {"name": "open invite link", "conversion": 0.62},
    {"name": "create account", "conversion": 0.58},
    {"name": "first board edit", "conversion": 0.78}
  ],
  "friction_experiments": [
    {"name": "remove the email verification gate before the first board edit", "target_step": "create account", "current_conversion": 0.58, "expected_conversion": 0.75},
    {"name": "open the shared board read-only before account creation", "target_step": "open invite link", "current_conversion": 0.62, "expected_conversion": 0.7}
  ],
  "events": [
    {"name": "invite_shown", "keys": ["invite_id", "inviter_user_id", "board_id"]},
    {"name": "invite_sent", "keys": ["invite_id", "inviter_user_id", "board_id"]},
    {"name": "invite_opened", "keys": ["invite_id", "inviter_user_id"]},
    {"name": "invite_accepted", "keys": ["invite_id", "inviter_user_id", "invitee_user_id"]},
    {"name": "invitee_activated", "keys": ["invite_id", "inviter_user_id", "invitee_user_id"]}
  ],
  "retention": {"invitee_d30": 0.41, "organic_d30": 0.38},
  "incentive": null,
  "consent_and_disclosure": {
    "recipient_source": "entered_by_inviter",
    "casl_express_consent": true,
    "gdpr_lawful_basis": "legitimate_interest",
    "compensation_disclosure": "not_applicable"
  }
}

{
  "loop_name": "refer a friend",
